var n={name:`@scscourt/design and @scscourt/design-theme`,version:`0.5.0 (pre-release, evaluated on the release branch)`,reportDate:`2026-09-30`,description:`The Angular component library and theme (Tailwind CSS v4 and daisyUI v5) of the Superior Court of California, County of Santa Clara. It is a set of building blocks: the conformance of an application depends on how it uses them and on its own content.`,contact:`The platform team (team-platform), which owns the library in the Atlas catalog.`,notes:`This report covers the components, the theme (light, dark and high contrast; comfortable and compact density) and the documentation demos. It does not cover the applications built with the library, which need their own reports. "Supports" here means the components meet the criterion when an application uses them as documented, including what each docs page lists under "What you must provide".`};var o=[{name:`Token contrast check`,status:`run`,detail:`171 colour pairings (57 per theme) measured from the OKLCH theme tokens by scripts/check-contrast.mjs on every npm test. All pass: 4.5 : 1 for text and 3 : 1 for large text and non-text in the light and dark themes; 7 : 1 and 4.5 : 1 in the high-contrast theme.`},{name:`Class pattern check`,status:`run`,detail:`scripts/check-a11y-classes.mjs fails on muted text below /70, outline-none without a replacement ring, text-warning on words and placeholder links. No findings.`},{name:`axe-core in jsdom`,status:`run`,detail:`Every demo on every component page and every reference-app route, with the WCAG 2.0, 2.1 and 2.2 A/AA rules (contrast and target size run in the browser instead). No violations.`},{name:`Playwright browser gate (npm run e2e:a11y)`,status:`run`,detail:`Every demo and route in the light, dark, high-contrast and compact runs: full axe including contrast, target size and 1.4.6 in high contrast; a Tab walk that checks each focus indicator and whether sticky content covers it; reflow at 320px; text spacing; reduced motion; forced colours. Last full run: 2,445 checks passed; the known-issue baseline (e2e/a11y-baseline.json) is empty.`},{name:`Keyboard specs`,status:`run`,detail:`Unit specs drive each composite widget with the keys of its WAI-ARIA Authoring Practices pattern and assert where focus goes.`},{name:`Manual protocol`,status:`scheduled`,detail:`Keyboard only; NVDA and JAWS with Chrome; VoiceOver on macOS and iOS; 200% and 400% zoom; the text-spacing bookmarklet; Windows contrast themes; reduced motion (ACCESSIBILITY.md). Scheduled before the 0.5.0 release; not yet run.`}];var i=[{standard:`WCAG 2.2 Level A`,included:`Yes`},{standard:`WCAG 2.2 Level AA`,included:`Yes`},{standard:`WCAG 2.2 Level AAA`,included:`Partly: 1.4.6 (high-contrast theme), 2.3.3, 2.4.12, 2.4.13 and 2.5.5 only`}];var s=[{term:`Supports`,meaning:`The functionality of the product has at least one method that meets the criterion without known defects or meets with equivalent facilitation.`},{term:`Partially Supports`,meaning:`Some functionality of the product does not meet the criterion, or, in this report, the criterion has not yet been verified by the manual protocol.`},{term:`Does Not Support`,meaning:`The majority of product functionality does not meet the criterion.`},{term:`Not Applicable`,meaning:`The criterion is not relevant to the product, or it is met by the application and its content rather than by the library (see "What applications must provide").`}];var e=`Automated checks pass; manual screen-reader verification pending.`;var t=`Automated checks pass; the manual keyboard-only pass is pending.`;var a=`Application responsibility (see "What applications must provide").`;var l=[{id:`1.1.1`,name:`Non-text Content`,level:`A`,conformance:`Partially Supports`,remarks:`Decorative icons are aria-hidden; icon-only buttons require a label; the image viewer requires alt; charts require a label and offer a data table. Alt text for content images is the application's. ${e}`},{id:`1.2.1`,name:`Audio-only and Video-only (Prerecorded)`,level:`A`,conformance:`Not Applicable`,remarks:`The library has no audio or video components. ${a}`},{id:`1.2.2`,name:`Captions (Prerecorded)`,level:`A`,conformance:`Not Applicable`,remarks:`The library has no audio or video components.`},{id:`1.2.3`,name:`Audio Description or Media Alternative (Prerecorded)`,level:`A`,conformance:`Not Applicable`,remarks:`The library has no audio or video components.`},{id:`1.3.1`,name:`Info and Relationships`,level:`A`,conformance:`Partially Supports`,remarks:`Native elements and landmarks; form fields and fieldsets link their label, hint and error; tables use header cells; components that render a heading take headingLevel. ${e}`},{id:`1.3.2`,name:`Meaningful Sequence`,level:`A`,conformance:`Partially Supports`,remarks:`Components render in reading order; a popup that opens in place comes right after its trigger. ${e}`},{id:`1.3.3`,name:`Sensory Characteristics`,level:`A`,conformance:`Partially Supports`,remarks:`Library text and labels do not refer to shape, colour or position. Not covered by the automated checks; manual review pending.`},{id:`1.4.1`,name:`Use of Color`,level:`A`,conformance:`Partially Supports`,remarks:`Alerts, banners and status components state their tone in words; charts add patterns and direct labels. The calendar event dots differ by colour only, so the application must show a legend. Manual review pending.`},{id:`1.4.2`,name:`Audio Control`,level:`A`,conformance:`Not Applicable`,remarks:`The library plays no audio.`},{id:`2.1.1`,name:`Keyboard`,level:`A`,conformance:`Partially Supports`,remarks:`Every interactive component is operable by keyboard, following its WAI-ARIA Authoring Practices pattern, and each docs page lists its keys. Dragging (form builder, panning) has button or key alternatives. ${t}`},{id:`2.1.2`,name:`No Keyboard Trap`,level:`A`,conformance:`Partially Supports`,remarks:`Only modal dialogs keep focus, and Escape closes them; Tab never indents in the rich-text editor. ${t}`},{id:`2.1.4`,name:`Character Key Shortcuts`,level:`A`,conformance:`Supports`,remarks:`Global shortcuts use a modifier (Ctrl/⌘+K for the command palette; editor and grid commands use Ctrl/⌘). Single keys act only while their widget has focus.`},{id:`2.2.1`,name:`Timing Adjustable`,level:`A`,conformance:`Partially Supports`,remarks:`Toasts pause while hovered or focused and never hold the only record of an outcome. The session-timeout warning lets the user extend the session. Manual verification pending.`},{id:`2.2.2`,name:`Pause, Stop, Hide`,level:`A`,conformance:`Partially Supports`,remarks:`Nothing auto-advances. Pulsing status dots and skeleton shimmer stop under the reduced-motion setting (OS or data-motion), but there is no on-page control to stop them; spinners and progress are loading indicators.`},{id:`2.3.1`,name:`Three Flashes or Below Threshold`,level:`A`,conformance:`Supports`,remarks:`No component flashes.`},{id:`2.4.1`,name:`Bypass Blocks`,level:`A`,conformance:`Supports`,remarks:`Every shell renders a skip link to its <main> landmark; axe bypass and landmark rules pass on every reference-app route. Applications that build their own chrome must add ScscSkipLink.`},{id:`2.4.2`,name:`Page Titled`,level:`A`,conformance:`Not Applicable`,remarks:`${a} provideScscRouteA11y() announces each route's title.`},{id:`2.4.3`,name:`Focus Order`,level:`A`,conformance:`Partially Supports`,remarks:`Dialogs, menus and popups move focus in and return it to the trigger; route changes focus the new page's heading. ${t}`},{id:`2.4.4`,name:`Link Purpose (In Context)`,level:`A`,conformance:`Partially Supports`,remarks:`Links the library renders (breadcrumbs, pagination, card links, view-document actions) are named for their target; link text in content is the application's. ${e}`},{id:`2.5.1`,name:`Pointer Gestures`,level:`A`,conformance:`Partially Supports`,remarks:`Zoom, page and move actions are buttons; no function needs a multipoint or path gesture. Manual verification on touch devices pending.`},{id:`2.5.2`,name:`Pointer Cancellation`,level:`A`,conformance:`Partially Supports`,remarks:`Actions run on click (the up event) on native buttons. A press outside an open popup closes it on pointer down. Manual verification pending.`},{id:`2.5.3`,name:`Label in Name`,level:`A`,conformance:`Partially Supports`,remarks:`Accessible names start with the visible label ("Copy code" for Copy). ${e}`},{id:`2.5.4`,name:`Motion Actuation`,level:`A`,conformance:`Not Applicable`,remarks:`No function is operated by device motion.`},{id:`3.1.1`,name:`Language of Page`,level:`A`,conformance:`Not Applicable`,remarks:`${a} The library's built-in words come from SCSC_LABELS in the application's language (English and Spanish packs).`},{id:`3.2.1`,name:`On Focus`,level:`A`,conformance:`Partially Supports`,remarks:`Focus alone never opens a menu or popup or changes context; tooltips show on focus and Escape hides them. Keyboard specs cover it; manual verification pending.`},{id:`3.2.2`,name:`On Input`,level:`A`,conformance:`Partially Supports`,remarks:`Changing the value of a control does not submit a form or navigate. Manual verification pending.`},{id:`3.2.6`,name:`Consistent Help`,level:`A`,conformance:`Not Applicable`,remarks:`${a} The mega footer has a contact block for it.`},{id:`3.3.1`,name:`Error Identification`,level:`A`,conformance:`Partially Supports`,remarks:`Field errors are text, prefixed "Error:" for screen readers, with aria-invalid; scsc-error-summary lists them and takes focus after a rejected submit. ${e}`},{id:`3.3.2`,name:`Labels or Instructions`,level:`A`,conformance:`Partially Supports`,remarks:`scsc-form-field and scsc-fieldset render a visible label, hint and required marker; the date and masked fields add a format hint. ${e}`},{id:`3.3.7`,name:`Redundant Entry`,level:`A`,conformance:`Not Applicable`,remarks:`${a}`},{id:`4.1.2`,name:`Name, Role, Value`,level:`A`,conformance:`Partially Supports`,remarks:`Custom widgets set the roles, states and properties of their APG pattern (each docs page lists them); axe passes on every demo in every state rendered. ${e}`},{id:`1.2.4`,name:`Captions (Live)`,level:`AA`,conformance:`Not Applicable`,remarks:`The library has no audio or video components.`},{id:`1.2.5`,name:`Audio Description (Prerecorded)`,level:`AA`,conformance:`Not Applicable`,remarks:`The library has no audio or video components.`},{id:`1.3.4`,name:`Orientation`,level:`AA`,conformance:`Supports`,remarks:`Nothing locks the display orientation; layouts respond to width.`},{id:`1.3.5`,name:`Identify Input Purpose`,level:`AA`,conformance:`Not Applicable`,remarks:`${a} Inputs are native elements and pass autocomplete through.`},{id:`1.4.3`,name:`Contrast (Minimum)`,level:`AA`,conformance:`Supports`,remarks:`Every sanctioned pairing is measured in all three themes (lowest text pairing 4.56 : 1 in light), and axe colour contrast passes on every demo and route in the browser. Colours an application adds are its own.`},{id:`1.4.4`,name:`Resize Text`,level:`AA`,conformance:`Partially Supports`,remarks:`Sizes are in rem and nothing that holds text has a fixed height. The manual 200% zoom pass is pending.`},{id:`1.4.5`,name:`Images of Text`,level:`AA`,conformance:`Supports`,remarks:`The library renders text as text; the court seal is a logo.`},{id:`1.4.10`,name:`Reflow`,level:`AA`,conformance:`Partially Supports`,remarks:`The 320px check passes on every demo and route; data tables, grids and documents scroll inside a named, focusable region (two-dimensional content). The manual 400% zoom pass is pending.`},{id:`1.4.11`,name:`Non-text Contrast`,level:`AA`,conformance:`Supports`,remarks:`Control borders, the focus ring and status marks are measured at 3 : 1 or more in every theme; chart palettes are 3 : 1 against the surface and between neighbouring series.`},{id:`1.4.12`,name:`Text Spacing`,level:`AA`,conformance:`Partially Supports`,remarks:`The automated text-spacing check (clipping and overflow) passes on every demo and route. The manual bookmarklet pass is pending.`},{id:`1.4.13`,name:`Content on Hover or Focus`,level:`AA`,conformance:`Partially Supports`,remarks:`Tooltips can be dismissed with Escape, stay open while hovered and do not time out; menus and popovers close with Escape. Manual verification pending.`},{id:`2.4.5`,name:`Multiple Ways`,level:`AA`,conformance:`Not Applicable`,remarks:`${a} The library provides navigation, search and command-palette components.`},{id:`2.4.6`,name:`Headings and Labels`,level:`AA`,conformance:`Partially Supports`,remarks:`Library labels describe their purpose and come from SCSC_LABELS; heading and label text in content is the application's. ${e}`},{id:`2.4.7`,name:`Focus Visible`,level:`AA`,conformance:`Supports`,remarks:`The theme draws a 2px ring on every focusable element; the browser Tab walk checks it at every stop in every theme and in forced colours.`},{id:`2.4.11`,name:`Focus Not Obscured (Minimum)`,level:`AA`,conformance:`Supports`,remarks:`The browser Tab walk checks that no sticky header, toast or FAB covers the focused element; scroll padding keeps it clear of the sticky masthead.`},{id:`2.5.7`,name:`Dragging Movements`,level:`AA`,conformance:`Partially Supports`,remarks:`Form-builder reordering has move up / move down buttons, file drop has a browse button, and the image viewer scrolls. The data grid resizes and reorders columns by dragging; its alternatives are keyboard commands, not single-pointer ones, so the grid does not yet meet this criterion.`},{id:`2.5.8`,name:`Target Size (Minimum)`,level:`AA`,conformance:`Supports`,remarks:`Targets are at least 24 × 24 px in compact density and larger in comfortable; axe target size passes in every run.`},{id:`3.1.2`,name:`Language of Parts`,level:`AA`,conformance:`Not Applicable`,remarks:`${a} Library strings follow the application's language pack.`},{id:`3.2.3`,name:`Consistent Navigation`,level:`AA`,conformance:`Not Applicable`,remarks:`${a} The shells keep navigation in the same place on every page.`},{id:`3.2.4`,name:`Consistent Identification`,level:`AA`,conformance:`Partially Supports`,remarks:`Shared words come from one label pack, so the same function has the same name in every component. Manual review pending.`},{id:`3.3.3`,name:`Error Suggestion`,level:`AA`,conformance:`Partially Supports`,remarks:`Error text is the application's; the library shows it with the field and in the error summary. ${e}`},{id:`3.3.4`,name:`Error Prevention (Legal, Financial, Data)`,level:`AA`,conformance:`Not Applicable`,remarks:`${a} The wizard review step and confirm dialogs support it.`},{id:`3.3.8`,name:`Accessible Authentication (Minimum)`,level:`AA`,conformance:`Not Applicable`,remarks:`${a} Library fields are native inputs.`},{id:`4.1.3`,name:`Status Messages`,level:`AA`,conformance:`Partially Supports`,remarks:`Results counts, saves, copies, page and month changes are announced through ScscAnnouncer or polite live regions without moving focus. ${e}`},{id:`1.4.6`,name:`Contrast (Enhanced)`,level:`AAA`,conformance:`Supports`,remarks:`In the high-contrast theme only: every text pairing is 7 : 1 or more (lowest 7.36 : 1), large text 4.5 : 1, and axe enhanced contrast passes there. The light and dark themes target AA.`},{id:`2.3.3`,name:`Animation from Interactions`,level:`AAA`,conformance:`Partially Supports`,remarks:`With the OS "reduce motion" setting, a global rule removes animations and transitions (the browser gate checks that none keep running). data-motion="reduced" on <html> removes movement from the motion tokens only. Open decision: the global rule ignores data-motion="full" and also removes short opacity fades.`},{id:`2.4.12`,name:`Focus Not Obscured (Enhanced)`,level:`AAA`,conformance:`Partially Supports`,remarks:`The browser Tab walk also checks that no part of the focused element is covered. One demo (the rating in a reactive form, compact density) failed once and passed on retry; it is being investigated.`},{id:`2.4.13`,name:`Focus Appearance`,level:`AAA`,conformance:`Supports`,remarks:`A 2px solid ring, offset 2px, measured at 3 : 1 or more against every surface in every theme; the system Highlight colour in forced colours.`},{id:`2.5.5`,name:`Target Size (Enhanced)`,level:`AAA`,conformance:`Partially Supports`,remarks:`In comfortable density, icon buttons, dismiss, clear and remove buttons, chips and pagination have 44 × 44 px hit areas (scsc-hit). Small text buttons (btn-sm) and checkboxes are smaller, and no automated check measures 44 px yet. Compact density targets 2.5.8 only.`}];var c=[{criterion:`2.4.2`,text:"A unique, descriptive `title` on every route."},{criterion:`3.1.1`,text:"The page language on `<html lang>`, and `lang` on passages in another language (3.1.2)."},{criterion:`1.1.1`,text:`Alt text for content images and image-viewer exhibits, and labels for icon-only buttons.`},{criterion:`1.3.1, 2.4.6`,text:"One `<h1>` per page, headings in order, and `headingLevel` on components that render a heading."},{criterion:`3.3.1, 3.3.3`,text:"Error messages that say what went wrong and how to fix it, and `scsc-error-summary` on a rejected submit."},{criterion:`1.3.5`,text:"`autocomplete` tokens on fields that collect the user’s own details."},{criterion:`3.2.6`,text:`Help (contact details, a help link or chat) in the same place on every page that offers it.`},{criterion:`3.3.7`,text:`Information the user already gave in a process filled in or offered for selection, not asked for again.`},{criterion:`3.3.8`,text:`Sign-in without a cognitive test: allow paste and password managers, or offer another method (a link or passkey).`},{criterion:`1.2.x`,text:`Captions, transcripts and audio description for any audio or video.`},{criterion:`2.4.5, 3.2.3`,text:`More than one way to reach each page, and navigation in the same order on every page.`}];export{o as a,n as i,i as n,s as o,l as r,c as t};